def template_report_html(frame, template_name, report_context):
    theme = REPORT_TEMPLATES[template_name]
    kpis = []
    for column in frame.columns:
        values = pd.to_numeric(
            frame[column].astype(str).str.replace(r"[$,%\s]", "", regex=True),
            errors="coerce",
        )
        if values.notna().sum() and values.notna().mean() >= 0.8:
            kpis.append((str(column), values.sum()))
        if len(kpis) == 4:
            break

    context_html = "".join(
        f"<li><strong>{html.escape(str(label))}:</strong> {html.escape(str(value))}</li>"
        for label, value in report_context.items()
    )
    kpi_html = "".join(
        f'<article class="kpi"><span>{html.escape(label)}</span><strong>{value:,.2f}</strong></article>'
        for label, value in kpis
    ) or '<p class="empty-kpis">No hay métricas numéricas en estos datos.</p>'
    table_html = frame.to_html(index=False, escape=True, classes="report-table", border=0)

    return f"""<!doctype html>
<html lang="es">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Reporte {html.escape(template_name)}</title>
